tool_input.command:
node << 'EOF'
import { generateReport } from './packages/frai-core/src/eval/index.js';

// Test case 1: No thresholds - should not add passed/thresholds fields
const report1 = generateReport({
  evaluations: [
    { id: 'exact_match', label: 'Exact Match', score: 0.85, total: 100 }
  ],
  outputsPath: 'outputs.json',
  referencesPath: 'references.json'
});

console.log('Test 1 - No thresholds:');
console.log('Has "passed":', 'passed' in report1);
console.log('Has "thresholds":', 'thresholds' in report1);

// Test case 2: With passing thresholds
const report2 = generateReport({
  evaluations: [
    { id: 'exact_match', label: 'Exact Match', score: 0.95, total: 100 },
    { id: 'toxicity', label: 'Toxicity', score: 0.99, total: 100 }
  ],
  outputsPath: 'outputs.json',
  referencesPath: 'references.json',
  thresholds: { exact_match: 0.9, toxicity: 0.98 }
});

console.log('\nTest 2 - All passing thresholds:');
console.log('report.passed:', report2.passed);
console.log('Thresholds:', JSON.stringify(report2.thresholds, null, 2));

// Test case 3: With failing thresholds
const report3 = generateReport({
  evaluations: [
    { id: 'exact_match', label: 'Exact Match', score: 0.85, total: 100 },
    { id: 'toxicity', label: 'Toxicity', score: 0.99, total: 100 }
  ],
  outputsPath: 'outputs.json',
  referencesPath: 'references.json',
  thresholds: { exact_match: 0.9, toxicity: 0.98 }
});

console.log('\nTest 3 - Some failing thresholds:');
console.log('report.passed:', report3.passed);
console.log('Thresholds:', JSON.stringify(report3.thresholds, null, 2));

// Test case 4: Missing metric (null score)
const report4 = generateReport({
  evaluations: [
    { id: 'exact_match', label: 'Exact Match', score: null, total: 0 }
  ],
  outputsPath: 'outputs.json',
  referencesPath: null,
  thresholds: { exact_match: 0.5 }
});

console.log('\nTest 4 - Missing metric score (null):');
console.log('report.passed:', report4.passed);
console.log('Thresholds:', JSON.stringify(report4.thresholds, null, 2));

EOF
